#!/usr/bin/env node
// semi-brand: builds a brand kit from its brand.json (docs/BRANDS.md). Runs inside the kit repo.
//   semi-brand build     validate brand.json, write dist/brand.css, dist/brand.json, BRAND.md, AGENTS.brand.md
//   semi-brand check     exit 1 when brand.json is invalid or a generated file is stale (the kit's CI / before a tag)
//   semi-brand preview   build, then serve the kit's own preview site locally (http://localhost:4600, --port N)
//   semi-brand site      build, then export the preview site as static files to .preview/out (GitHub Pages;
//                        SEMI_BRAND_BASE_PATH=/<repo> sets the path it is served under)
//   semi-brand storybook print the Semi Storybook "Brand preview" link for this brand.json (before a kit exists)
// The preview site template ships in @semi/ui (brand/preview) and is copied into .preview/ (gitignored) on each run,
// so a newer @semi/ui brings a newer preview.
import { copyFileSync, cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { extname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { generateBrand, SHADES } from "./generate.mjs";

const PREVIEW_URL = "https://hoanghuynh296.github.io/semi-nextjs-codebase/brand.html";
const pkgRoot = fileURLToPath(new URL("..", import.meta.url));
const readJson = (p) => JSON.parse(readFileSync(p, "utf8"));

/** next/font module for the brand's fonts: the variables next/font sets, as one className string. */
function fontsModule(fonts) {
  const id = (f) => f.nextFont.replace(/_(\w)/g, (_, c) => c.toUpperCase()).replace(/^\w/, (c) => c.toLowerCase());
  return [
    "// GENERATED by semi-brand: the brand's fonts (dist/brand.json). Do not edit.",
    `import { ${fonts.map((f) => f.nextFont).join(", ")} } from "next/font/google";`,
    "",
    ...fonts.map((f) => `const ${id(f)} = ${f.nextFont}({ subsets: ["latin", "vietnamese"], ${f.weight ? `weight: ${JSON.stringify(f.weight)}, ` : ""}variable: "${f.variable}" });`),
    "",
    `export const fontVariables = [${fonts.map((f) => `${id(f)}.variable`).join(", ")}].join(" ");`,
    "",
  ].join("\n");
}

/** Copy the preview site template into <kit>/.preview and add this brand's data (after a build). */
export function preparePreview(cwd) {
  const dir = join(cwd, ".preview");
  rmSync(join(dir, "app"), { recursive: true, force: true });
  cpSync(join(pkgRoot, "brand", "preview"), dir, { recursive: true });
  const kit = readJson(join(cwd, "dist", "brand.json"));
  cpSync(join(cwd, "dist", "brand.css"), join(dir, "app", "brand.css"));
  writeFileSync(join(dir, "app", "brand.json"), JSON.stringify(kit, null, 2) + "\n");
  writeFileSync(join(dir, "app", "fonts.js"), fontsModule(kit.fonts));
  rmSync(join(dir, "public", "logo"), { recursive: true, force: true });
  if (existsSync(join(cwd, "dist", "logo"))) cpSync(join(cwd, "dist", "logo"), join(dir, "public", "logo"), { recursive: true });
  return dir;
}

/** Run the kit's own Next.js (node_modules/.bin/next) in .preview. */
function next(cwd, args) {
  const bin = join(cwd, "node_modules", ".bin", process.platform === "win32" ? "next.cmd" : "next");
  if (!existsSync(bin)) {
    console.error("semi-brand: thiếu next trong brand kit. Chạy npm install (devDependencies: next, react, react-dom, tailwindcss, @tailwindcss/postcss).");
    return 2;
  }
  return spawnSync(bin, args, { cwd: join(cwd, ".preview"), stdio: "inherit", env: process.env }).status ?? 1;
}

/** brand.json → { files: { path: content }, result } (nothing written). */
export function buildKit(cwd) {
  const brand = readJson(join(cwd, "brand.json"));
  const tokens = readJson(join(pkgRoot, "tokens/tokens.json"));
  const styles = readJson(join(pkgRoot, "tokens/styles.json"));
  const version = readJson(join(pkgRoot, "package.json")).version;
  const result = generateBrand(brand, { tokens, styles, version });
  // Logo files live in the kit repo (brand.json "logo"); the build copies them to dist/logo/ so products import them
  // from the package (@scope/brand/dist/logo/…) and the preview shows them.
  const logo = result.tokens.guide.logo;
  const assets = {};
  if (logo) {
    const missing = [];
    for (const k of ["full", "fullDark", "mark"]) {
      if (!logo[k]) continue;
      if (!existsSync(join(cwd, logo[k]))) missing.push(`logo.${k}: không thấy ${logo[k]}`);
      else (assets[`dist/logo/${k}${extname(logo[k]).toLowerCase()}`] = join(cwd, logo[k])), (logo[`${k}Dist`] = `dist/logo/${k}${extname(logo[k]).toLowerCase()}`);
    }
    if (missing.length) throw Object.assign(new Error(`brand.json không hợp lệ:\n- ${missing.join("\n- ")}`), { errors: missing });
  }
  const files = {
    "dist/brand.css": result.css,
    "dist/brand.json": JSON.stringify({ $note: "GENERATED by semi-brand from brand.json — do not edit.", semiVersion: version, ...result.tokens, report: result.report, warnings: result.warnings }, null, 2) + "\n",
    "BRAND.md": brandMd(result, styles),
    "AGENTS.brand.md": agentsMd(result, styles),
  };
  return { files, assets, result };
}

const swatches = (sc) => SHADES.map((s) => `| ${s} | \`${sc[s]}\` |`).join("\n");
const styleName = (styles, id) => styles.styles.find((s) => s.id === id)?.name ?? id;

const bullets = (list) => list.map((x) => `- ${x}`).join("\n");
const exampleRows = (ex) =>
  Object.entries(ex)
    .map(([k, v]) => `| ${{ button: "Nút", success: "Thành công", error: "Lỗi", empty: "Trạng thái trống", confirm: "Hỏi xác nhận" }[k] ?? k} | ${(Array.isArray(v) ? v : [v]).map((x) => `“${x}”`).join(" · ")} |`)
    .join("\n");

/** Sections every guideline shares: brief, logo, colour use, voice, imagery. md = BRAND.md (people), agents = rules. */
function guideMd(t) {
  const g = t.guide;
  const out = [];
  if (g.brief) {
    out.push("## Thương hiệu này cho ai\n");
    if (g.brief.product) out.push(`**Sản phẩm:** ${g.brief.product}  `);
    if (g.brief.audience) out.push(`**Người dùng:** ${g.brief.audience}  `);
    if (g.brief.personality?.length) out.push(`**Tính cách:** ${g.brief.personality.join(", ")}`);
    out.push("");
  }
  if (g.logo) {
    const l = g.logo;
    out.push("## Logo\n");
    out.push("| Bản | File trong package | Dùng khi |\n|---|---|---|");
    out.push(`| Đầy đủ | \`${t.package}/${l.fullDist}\` | Header, trang đăng nhập, email${l.fullDark ? " (nền sáng)" : ""} |`);
    if (l.fullDark) out.push(`| Đầy đủ, nền tối | \`${t.package}/${l.fullDarkDist}\` | Theme tối |`);
    if (l.mark) out.push(`| Biểu tượng | \`${t.package}/${l.markDist}\` | Favicon, icon app, sidebar thu gọn, avatar |`);
    out.push("");
    out.push(bullets([
      `Khoảng trống quanh logo ít nhất ${l.clearspace} × chiều cao logo; không đặt chữ, viền hay ảnh vào vùng đó`,
      `Rộng tối thiểu ${l.minWidth}px cho bản đầy đủ${l.mark ? "; nhỏ hơn thì dùng biểu tượng" : ""}`,
      "Không kéo méo, xoay, đổi màu, thêm bóng hay viền; không đặt lên ảnh rối",
      l.fullDark ? "Theme tối dùng bản nền tối" : "Chỉ có một bản: kiểm tra logo vẫn rõ trên nền tối trước khi dùng ở theme tối",
    ]));
    out.push("");
  }
  out.push("## Cách dùng màu\n");
  out.push(`**Mức dùng màu chính: ${g.color.accentLabel}.** ${g.color.accentRule}\n`);
  out.push(bullets([
    "Màu chính là màu của hành động: nút chính (`bg-accent` + `text-on-accent`), link và chữ nhấn (`text-accent-fg`), mục đang chọn (`bg-accent-subtle`, `border-accent-line`), focus (`ring-focus`)",
    ...(g.color.secondaryRule ? [`Màu phụ chỉ cho ${g.color.secondaryRule}; không dùng cho nút hành động`] : []),
    "Thành công / lỗi / cảnh báo giữ màu trạng thái của Semi (`text-success-fg`, `bg-danger-bg` …), không dùng màu thương hiệu để báo trạng thái",
    "Nền, chữ, viền: token ngữ nghĩa (`bg-panel`, `text-muted`, `border-line`), không mã màu",
  ]));
  out.push("");
  const v = g.voice;
  out.push("## Giọng văn\n");
  out.push(`**Giọng: ${v.toneLabel}.** Gọi người dùng là “${v.address}”, thương hiệu tự xưng “${v.we}”. Emoji: ${v.emoji ? "được dùng, tiết chế, không trong lỗi" : "không"}.${v.custom ? "" : " *(mặc định của Semi: thương hiệu chưa chọn giọng văn)*"}\n`);
  out.push(bullets(v.rules));
  if (v.do.length) out.push(`\n**Nên**\n\n${bullets(v.do)}`);
  if (v.dont.length) out.push(`\n**Không nên**\n\n${bullets(v.dont)}`);
  if (Object.keys(v.examples).length) out.push(`\n| Chỗ | Ví dụ |\n|---|---|\n${exampleRows(v.examples)}`);
  out.push("");
  if (g.imagery) out.push(`## Hình ảnh và minh hoạ\n\n${g.imagery}\n\nIcon: bộ icon của Semi (\`<Icon name>\`, nét 1.75), không trộn bộ icon khác.\n`);
  return out.join("\n");
}

function brandMd({ tokens: t, report, warnings }, styles) {
  const allowed = t.styles.allowed.map((id) => `${styleName(styles, id)}${id === t.styles.default ? " (mặc định)" : ""}`).join(", ");
  const font = (role) => t.fonts.find((f) => f.roles.includes(role)).family;
  return `<!-- GENERATED by semi-brand from brand.json — do not edit. -->
# ${t.name}: brand guideline

Bộ nhận diện của **${t.name}** trên Semi Design System. Mọi sản phẩm cài \`${t.package}\` và dùng đúng các giá trị này;
không định nghĩa màu, font hay style riêng trong sản phẩm. Muốn đổi: sửa \`brand.json\` trong repo brand rồi chạy
\`/semi-brand\` (xem \`@semi/ui/docs/BRANDS.md\`).

## Lựa chọn

| | |
|---|---|
| Màu chính | \`${t.primary[t.brandStep ?? 500]}\` (nằm ở \`primary-${t.brandStep ?? 500}\`) |
| Màu phụ | ${t.secondary ? `\`${t.secondary[t.secondaryStep ?? 500]}\` (nằm ở \`secondary-${t.secondaryStep ?? 500}\`)` : "không có"} |
| Màu trung tính | ${t.neutral === "tinted" ? "phủ theo màu chính" : "có sẵn của style"} |
| Style | ${allowed} |
| Font | ${font("sans")} (giao diện, nội dung) · ${font("display")} (tiêu đề, số KPI) |
| Giọng văn | ${t.guide.voice.toneLabel}, gọi người dùng “${t.guide.voice.address}” |

${guideMd(t)}
## Màu chính (\`primary-*\`)

| Sắc độ | Mã |
|---|---|
${swatches(t.primary)}
${t.secondary ? `\n## Màu phụ (\`secondary-*\`)\n\n| Sắc độ | Mã |\n|---|---|\n${swatches(t.secondary)}\n` : ""}
## Token màu trong sản phẩm

| Việc | Token | Tối | Sáng |
|---|---|---|---|
| Nút chính | \`bg-accent\` + \`text-on-accent\` (hoặc \`Button variant="primary"\`) | \`${t.themes.dark["color-accent"]}\` / \`${t.themes.dark["color-on-accent"]}\` | \`${t.themes.light["color-accent"]}\` / \`${t.themes.light["color-on-accent"]}\` |
| Chữ, icon màu chính | \`text-accent-fg\` | \`${t.themes.dark["color-accent-fg"]}\` | \`${t.themes.light["color-accent-fg"]}\` |
| Viền focus, ô nhập đang gõ | \`ring-focus\`, \`border-focus\` | \`${t.themes.dark["color-accent-fg"]}\` | \`${t.themes.light["color-accent-fg"]}\` |
| Mục đang chọn (nền nhạt, viền) | \`bg-accent-subtle\`, \`border-accent-line\` | nhạt từ \`${t.themes.dark["color-accent-fg"]}\` | nhạt từ \`${t.themes.light["color-accent-fg"]}\` |
${t.secondary ? `| Chữ màu phụ | \`text-secondary-fg\` | \`${t.themes.dark["color-secondary-fg"]}\` | \`${t.themes.light["color-secondary-fg"]}\` |\n| Nền màu phụ | \`bg-secondary-solid\` + \`text-on-secondary\` | \`${t.themes.dark["color-secondary-solid"]}\` / \`${t.themes.dark["color-on-secondary"]}\` | \`${t.themes.light["color-secondary-solid"]}\` / \`${t.themes.light["color-on-secondary"]}\` |\n` : ""}
Không dùng \`primary-500/15\`, \`ring-primary-500/50\` … cho trạng thái: thang \`primary-*\` không đổi theo theme nên có
thể biến mất trên nền (\`semi-lint\`: \`accent-state-token\`).${["dark", "light"].some((th) => t.fidelity?.[th]?.deltaE > 0.08) ? `\n\nNút chính không phải đúng mã màu thương hiệu ở theme ${["dark", "light"].filter((th) => t.fidelity[th].deltaE > 0.08).map((th) => (th === "dark" ? "tối" : "sáng")).join(" và ")}: đó là sắc độ gần nhất đọc rõ và tách khỏi nền (xem Lưu ý). Logo và hình ảnh vẫn dùng đúng mã.` : ""}

## Kiểm tra đọc rõ (chữ ≥ 4.5:1, viền và nút so với nền ≥ 3:1)

| Kiểm tra | Cặp | Tỉ lệ | Cần | |
|---|---|---:|---:|---|
${report.map((r) => `| ${r.check} | ${r.pair} | ${r.ratio.toFixed(2)} | ${r.min} | ${r.ok ? "đạt" : r.soft ? "lưu ý" : "**chưa đạt**"} |`).join("\n")}
${warnings.length ? `\n## Lưu ý\n\n${warnings.map((w) => `- ${w}`).join("\n")}\n` : ""}`;
}

/** Rules for every agent working in a product of this brand: decisions, not only prohibitions. */
function agentsMd({ tokens: t }, styles) {
  const g = t.guide;
  const v = g.voice;
  const allowed = t.styles.allowed.map((id) => `\`${id}\``).join(", ");
  const lines = [
    `This product belongs to the **${t.name}** brand. Colours, fonts, logo, voice and allowed styles come only from \`${t.package}\` (full guideline: \`node_modules/${t.package}/BRAND.md\`; with the Semi MCP server, \`semi_brand\` answers from it).`,
    "",
    "**Colour**",
    `- Accent use: **${g.color.accentLabel}**. ${g.color.accentRule}`,
    "- One primary button per area (`Button variant=\"primary\"`); everything else secondary or ghost.",
    "- States: `ring-focus`, `border-focus`, `bg-accent-subtle`, `border-accent-line`; coloured text `text-accent-fg`. Never `primary-500/15`-style classes (`accent-state-token`).",
    ...(g.color.secondaryRule ? [`- Secondary colour only for ${g.color.secondaryRule}. Never a secondary-coloured action button.`] : ["- This brand has no secondary colour: do not add one."]),
    "- Status (success, error, warning) keeps Semi's status tokens, never the brand colour.",
    `- Never define brand colours or override Semi tokens in this app (\`--color-primary-*\`, \`--semi-*\`, \`@theme\` colours, hex values): \`semi-lint\` blocks it (\`brand-override\`).`,
    "",
    "**Type and style**",
    `- Style: ${allowed} only (\`data-style\` on \`<html>\`, \`"style"\` in \`semi-lint.json\`, switch with \`/semi-style\`). No \`data-palette\`: the brand sets the neutrals.`,
    `- Fonts: ${t.fonts.map((f) => f.family).join(" + ")}, loaded with \`next/font\` in the root layout (\`${t.fonts.map((f) => f.variable).join("`, `")}\`). Titles and KPI figures \`font-display\`, everything else \`font-sans\`.`,
    "",
    ...(g.logo
      ? [
          "**Logo**",
          `- Import from \`${t.package}/${g.logo.fullDist}\`${g.logo.fullDark ? ` (dark theme: \`${t.package}/${g.logo.fullDarkDist}\`)` : ""}${g.logo.mark ? `; favicon, app icon and collapsed sidebar: \`${t.package}/${g.logo.markDist}\`` : ""}. Never redraw, recolour or stretch it.`,
          `- Clear space ${g.logo.clearspace} × its height; full logo at least ${g.logo.minWidth}px wide.`,
          "",
        ]
      : []),
    `**Voice (UI text)** — ${v.toneLabel}. Address the user as “${v.address}”; the brand says “${v.we}”. Emoji: ${v.emoji ? "allowed sparingly, never in errors" : "none"}. Write UI text in the product's language (Vietnamese unless the product says otherwise).`,
    ...v.rules.map((r) => `- ${r}`),
    ...v.do.map((r) => `- Do: ${r}`),
    ...v.dont.map((r) => `- Don't: ${r}`),
    ...Object.entries(v.examples).map(([k, x]) => `- Example (${k}): ${(Array.isArray(x) ? x : [x]).map((y) => `“${y}”`).join(" · ")}`),
    ...(g.brief?.audience || g.brief?.personality?.length ? ["", `**Who it is for** — ${[g.brief.audience, g.brief.personality?.length ? `personality: ${g.brief.personality.join(", ")}` : null].filter(Boolean).join("; ")}. Choose words, density and imagery for them.`] : []),
    ...(g.imagery ? ["", `**Imagery** — ${g.imagery}`] : []),
    "",
    "A change to the brand happens in the brand repo (`/semi-brand`), then `/semi-update` here.",
  ];
  return `<!-- semi-brand:start -->\n## Brand: ${t.name} (\`${t.package}\`)\n\n${lines.join("\n")}\n<!-- semi-brand:end -->\n`;
}

function main(argv) {
  const cmd = argv[0];
  const cwd = process.cwd();
  if (!["build", "check", "preview", "site", "storybook"].includes(cmd)) {
    console.log("usage: semi-brand build | check | preview [--port N] | site | storybook   (in a brand kit repo with brand.json)");
    return cmd ? 2 : 0;
  }
  if (!existsSync(join(cwd, "brand.json"))) {
    console.error("semi-brand: không thấy brand.json ở thư mục này (tạo brand kit bằng /semi-brand)");
    return 2;
  }
  if (cmd === "storybook") {
    const json = readFileSync(join(cwd, "brand.json"), "utf8");
    console.log(`${PREVIEW_URL}#brand=${Buffer.from(JSON.stringify(JSON.parse(json))).toString("base64url")}`);
    return 0;
  }
  let built;
  try {
    built = buildKit(cwd);
  } catch (e) {
    console.error(e.message);
    return 1;
  }
  const { files, assets, result } = built;
  if (cmd === "check") {
    const stale = Object.entries(files).filter(([p, c]) => !existsSync(join(cwd, p)) || readFileSync(join(cwd, p), "utf8") !== c).map(([p]) => p);
    for (const [p, from] of Object.entries(assets)) if (!existsSync(join(cwd, p)) || !readFileSync(join(cwd, p)).equals(readFileSync(from))) stale.push(p);
    if (stale.length) console.error(`semi-brand: chưa sinh lại (chạy semi-brand build): ${stale.join(", ")}`);
    const failing = result.report.filter((r) => !r.ok && !r.soft);
    if (failing.length) console.error(`semi-brand: chưa đạt AA: ${failing.map((r) => r.check).join(", ")}`);
    if (!stale.length && !failing.length) console.log(`semi-brand: ${result.tokens.name} hợp lệ, file đã sinh khớp`);
    return stale.length || failing.length ? 1 : 0;
  }
  mkdirSync(join(cwd, "dist"), { recursive: true });
  rmSync(join(cwd, "dist", "logo"), { recursive: true, force: true });
  for (const [p, c] of Object.entries(files)) writeFileSync(join(cwd, p), c);
  for (const [p, from] of Object.entries(assets)) mkdirSync(join(cwd, "dist", "logo"), { recursive: true }), copyFileSync(from, join(cwd, p));
  const ok = result.report.filter((r) => r.ok || r.soft).length;
  console.log(`semi-brand: ${result.tokens.name}: ${Object.keys(files).join(", ")} · đọc rõ ${ok}/${result.report.length} cặp đạt AA`);
  for (const w of result.warnings) console.log(`  lưu ý: ${w}`);
  const passed = result.report.every((r) => r.ok || r.soft);
  if (cmd === "build") {
    // A running preview (semi-brand preview) picks the new colours up right away.
    if (existsSync(join(cwd, ".preview", "app"))) preparePreview(cwd);
    return passed ? 0 : 1;
  }

  preparePreview(cwd);
  if (cmd === "site") {
    const status = next(cwd, ["build"]);
    if (status === 0) console.log(`semi-brand: trang preview tĩnh ở .preview/out${process.env.SEMI_BRAND_BASE_PATH ? ` (đường dẫn ${process.env.SEMI_BRAND_BASE_PATH})` : ""}`);
    return status;
  }
  const i = argv.indexOf("--port");
  const port = i > 0 && argv[i + 1] ? argv[i + 1] : process.env.PORT || "4600";
  console.log(`semi-brand: xem trước ${result.tokens.name} ở http://localhost:${port} (Ctrl+C để dừng)`);
  return next(cwd, ["dev", "--port", port]);
}

const isMain = process.argv[1] && /(semi-brand|brand[\\/]cli\.mjs)$/.test(process.argv[1]);
if (isMain) process.exit(main(process.argv.slice(2)));
